package com.dukaops.backend.reports;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.dukaops.backend.auth.TenantUserPrincipal;

@Service
public class ReportsService {
    @org.springframework.beans.factory.annotation.Autowired private com.dukaops.backend.auth.AccessPolicy accessPolicy;
    @PersistenceContext private EntityManager em;
    private Map<String,Object> params(TenantUserPrincipal p, UUID branch, Instant from, Instant to) { if (p.getRole() == com.dukaops.backend.auth.UserRole.STAFF) throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN, "Reports are not available to staff."); if (p.getRole() == com.dukaops.backend.auth.UserRole.MANAGER && branch == null) throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST, "Select an assigned branch for this report."); if (branch != null) accessPolicy.requireBranch(p, branch); Map<String,Object> x = new HashMap<>(); x.put("tenantId", p.getTenantId()); x.put("branchId", branch); x.put("from", from); x.put("to", to); return x; }
    private List<?> query(String sql, Map<String,Object> values) { var q = em.createNativeQuery(sql); q.getParameters().forEach(parameter -> q.setParameter(parameter.getName(), values.get(parameter.getName()))); return q.getResultList(); }
    private String filters() { return " and (cast(:branchId as uuid) is null or branch_id=:branchId) and (cast(:from as timestamptz) is null or created_at>=:from) and (cast(:to as timestamptz) is null or created_at<:to)"; }
    @Transactional(readOnly=true) public Map<String,Object> overview(TenantUserPrincipal p, UUID b, Instant f, Instant t) { var x=params(p,b,f,t); var r=query("select coalesce(sum(total_amount),0),count(*) from sales_orders where tenant_id=:tenantId and status='COMPLETED'"+filters(),x); Object[] v=(Object[])r.get(0); long count=((Number)v[1]).longValue(); Map<String,Object> out=new LinkedHashMap<>(); out.put("revenue",v[0]); out.put("completedSales",v[1]); out.put("totalOrders",query("select count(*) from sales_orders where tenant_id=:tenantId"+filters(),x).get(0)); out.put("averageSaleValue",count==0?BigDecimal.ZERO:new BigDecimal(v[0].toString()).divide(BigDecimal.valueOf(count),2,RoundingMode.HALF_UP)); out.put("activeProducts",query("select count(*) from products where tenant_id=:tenantId and status='ACTIVE' and (cast(:branchId as uuid) is null or id in (select product_id from stock_levels where tenant_id=:tenantId and branch_id=:branchId))",x).get(0)); out.put("lowStockProducts",query("select count(*) from stock_levels where tenant_id=:tenantId and quantity<=reorder_level and (cast(:branchId as uuid) is null or branch_id=:branchId)",x).get(0)); out.put("customers",p.getRole() == com.dukaops.backend.auth.UserRole.MANAGER ? null : query("select count(*) from customers where tenant_id=:tenantId and status='ACTIVE'",x).get(0)); return out; }
    @Transactional(readOnly=true) public Map<String,Object> sales(TenantUserPrincipal p, UUID b, Instant f, Instant t) { var x=params(p,b,f,t); Map<String,Object> out=new LinkedHashMap<>(); out.put("summary",overview(p,b,f,t)); out.put("byDay",query("select date_trunc('day',created_at),coalesce(sum(total_amount),0),count(*) from sales_orders where tenant_id=:tenantId and status='COMPLETED'"+filters()+" group by 1 order by 1",x)); out.put("byPaymentMethod",query("select p.method,coalesce(sum(p.amount),0),count(*) from sales_payments p join sales_orders o on o.id=p.order_id where p.tenant_id=:tenantId and o.status='COMPLETED' and (cast(:branchId as uuid) is null or o.branch_id=:branchId) and (cast(:from as timestamptz) is null or o.created_at>=:from) and (cast(:to as timestamptz) is null or o.created_at<:to) group by p.method",x)); out.put("transactions",query("select id,customer_name,status,total_amount,created_at,branch_id from sales_orders where tenant_id=:tenantId"+filters()+" order by created_at desc limit 100",x)); return out; }
    @Transactional(readOnly=true) public Map<String,Object> inventory(TenantUserPrincipal p, UUID b) { var x=params(p,b,null,null); Map<String,Object> out=new LinkedHashMap<>(); out.put("stock",query("select branch_id,product_id,quantity,reorder_level from stock_levels where tenant_id=:tenantId and (cast(:branchId as uuid) is null or branch_id=:branchId) order by quantity",x)); out.put("movements",query("select id,branch_id,product_id,movement_type,quantity_change,quantity_after,created_at from stock_movements where tenant_id=:tenantId and (cast(:branchId as uuid) is null or branch_id=:branchId) order by created_at desc limit 100",x)); return out; }
    @Transactional(readOnly=true) public Map<String,Object> products(TenantUserPrincipal p, UUID b, Instant f, Instant t) { var x=params(p,b,f,t); Map<String,Object> out=new LinkedHashMap<>(); out.put("bestSelling",query("select i.product_id,sum(i.quantity),sum(i.line_total) from sales_order_items i join sales_orders o on o.id=i.order_id where i.tenant_id=:tenantId and o.status='COMPLETED' and (cast(:branchId as uuid) is null or o.branch_id=:branchId) and (cast(:from as timestamptz) is null or o.created_at>=:from) and (cast(:to as timestamptz) is null or o.created_at<:to) group by i.product_id order by sum(i.quantity) desc limit 20",x)); return out; }
    @Transactional(readOnly=true) public Map<String,Object> customers(TenantUserPrincipal p) { if (!accessPolicy.businessAdmin(p)) throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN, "Business-wide contact reports require administrator access."); var x=params(p,null,null,null); Map<String,Object> out=new LinkedHashMap<>(); out.put("total",query("select count(*) from customers where tenant_id=:tenantId",x).get(0)); out.put("active",query("select count(*) from customers where tenant_id=:tenantId and status='ACTIVE'",x).get(0)); return out; }
    @Transactional(readOnly=true) public Map<String,Object> suppliers(TenantUserPrincipal p) { if (!accessPolicy.businessAdmin(p)) throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN, "Business-wide contact reports require administrator access."); var x=params(p,null,null,null); Map<String,Object> out=new LinkedHashMap<>(); out.put("total",query("select count(*) from suppliers where tenant_id=:tenantId",x).get(0)); out.put("active",query("select count(*) from suppliers where tenant_id=:tenantId and status='ACTIVE'",x).get(0)); return out; }
    public String export(TenantUserPrincipal p, String type, UUID branch) { if (!"sales".equalsIgnoreCase(type)) return "type,message\n"+csv(type)+",No export data available\n"; StringBuilder out=new StringBuilder("id,customer,status,total,createdAt,branchId\n"); for(Object row:sales(p,branch,null,null).get("transactions") instanceof List<?> list?list:List.of()){ Object[] values=(Object[])row; for(int i=0;i<values.length;i++){if(i>0)out.append(',');out.append(csv(values[i]));}out.append('\n'); } return out.toString(); }
    private String csv(Object value) { String s=String.valueOf(value==null?"":value); if(s.startsWith("=")||s.startsWith("+")||s.startsWith("-")||s.startsWith("@"))s="'"+s; return "\""+s.replace("\"","\"\"")+"\""; }
}
